const webhookItem = $('Telegram Webhook Trigger').first()?.json || {};
const update = webhookItem.body || webhookItem || {};
const pgData = $('Postgres: Load Vault, EOD Logs & Bot State').first()?.json || {};
const jobRows = $('Read Job Application Sheet').all().map(i => i.json);

const vaultRows = Array.isArray(pgData.vault_rows) ? pgData.vault_rows : [];
const eodLogs = Array.isArray(pgData.eod_logs) ? pgData.eod_logs : [];
const followupDrafts = Array.isArray(pgData.followup_drafts) ? pgData.followup_drafts : [];
const botState = pgData.bot_state || {};
const learnedRulesCount = Number(pgData.learned_rules_count || 0);

const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const ADMIN_CHAT_ID = '8873019272';
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_DOCUMENT_ID/edit';

const msg = update.message || update.callback_query?.message || {};
const chatId = String(msg.chat?.id || update.callback_query?.from?.id || ADMIN_CHAT_ID);
const text = String(update.message?.text || '').trim();
const cbData = String(update.callback_query?.data || '').trim();
const cbId = update.callback_query?.id;

async function tgPost(endpoint, body) {
  try {
    const r = await fetch(`https://api.telegram.org/bot${TG_TOKEN}/${endpoint}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    return await r.json();
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

if (cbId) {
  await tgPost('answerCallbackQuery', { callback_query_id: cbId, text: '⚡ Processing on Hostinger n8n...' });
}

if (chatId !== ADMIN_CHAT_ID) {
  return [{ json: { ok: false, ignored: true, reason: 'Unauthorized chat_id' } }];
}

const sheetUpdates = [];
const trackerUpdates = [];
const sqlQueries = [];

const mainMenuKeyboard = [
  [
    { text: '📊 Live Pipeline', callback_data: 'cmd:pipeline' },
    { text: '📝 Pending Reviews', callback_data: 'cmd:drafts' }
  ],
  [
    { text: '🌙 EOD Summary', callback_data: 'cmd:eod' },
    { text: '✨ Auto-Enrich Sheet', callback_data: 'cmd:enrich' }
  ],
  [
    { text: '🔐 Credential Vault (008/08)', callback_data: 'cmd:edit_creds' },
    { text: '📬 Follow-Up Drafts', callback_data: 'cmd:mail_drafts' }
  ],
  [
    { text: '🔄 Sync Portals & Certs (WF B)', callback_data: 'cmd:sync_profile' }
  ]
];

function findRowBySNo(sNo) {
  return jobRows.find(r => String(r['S. No.'] || '').trim() === String(sNo).trim());
}

function getClickableJdUrl(row) {
  const pageLink = String(row?.['Applied Page link'] || '').trim();
  if (pageLink) return pageLink;
  const jd = String(row?.['Position - Description'] || '');
  const m = jd.match(/https?:\/\/[^\s)]+/i);
  if (m) return m[0];
  const site = String(row?.['Company website'] || '').trim();
  return site || SHEET_URL;
}

const action = cbData || text || '/menu';

// 1. Check if user is replying with text to a pending state (Rework Note or Portal Password or QA Answer)
if (!cbData && text && !text.startsWith('/') && botState.pending_action) {
  const pAct = botState.pending_action;
  const targetId = botState.target_id;
  const scope = botState.scope || 'ONE_OFF';

  if (pAct === 'REWORK_RESUME') {
    const noteText = scope === 'ONE_OFF'
      ? `[For this resume only] ${text}`
      : text;
    sheetUpdates.push({
      'S. No.': String(targetId),
      'Notes by Reviewer': noteText,
      'Resume Status': 'Needs Rework'
    });
    if (scope === 'LEARN') {
      const safeRule = text.replace(/'/g, "''");
      sqlQueries.push(`INSERT INTO learned_rules (section_name, role_category, rule_instruction, triggered_by_comment, is_active) VALUES ('global', 'ALL', '${safeRule}', '${safeRule}', TRUE);`);
    }
    sqlQueries.push(`DELETE FROM job_hunter_bot_state WHERE chat_id = '${ADMIN_CHAT_ID}';`);
    const row = findRowBySNo(targetId);
    await tgPost('sendMessage', {
      chat_id: ADMIN_CHAT_ID,
      parse_mode: 'Markdown',
      disable_web_page_preview: true,
      text:
        `🛠️ *Resume Rework Queued for Row #${targetId} (${row?.['Company'] || 'Target'})*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `📝 *Your Feedback:* "${text}"\n` +
        `🎯 *Scope:* *${scope === 'ONE_OFF' ? '📌 This Job Only (Not saved to Lessons Learnt)' : '🧠 Saved to Permanent Lessons Learnt'}*\n` +
        `🔗 [View JD](${getClickableJdUrl(row)})\n\n` +
        `_Workflow 2 on Hostinger n8n will automatically rewrite the flagged section, re-render the 1-page PDF via Gotenberg, and send you the revised link!_`,
      reply_markup: { inline_keyboard: mainMenuKeyboard }
    });
  } else if (pAct === 'REWORK_CL') {
    const noteText = scope === 'ONE_OFF'
      ? `[For this cover letter only] ${text}`
      : text;
    sheetUpdates.push({
      'S. No.': String(targetId),
      'Notes for CL': noteText,
      'Cover Letter Status': 'Needs Rework'
    });
    if (scope === 'LEARN') {
      const safeRule = text.replace(/'/g, "''");
      sqlQueries.push(`INSERT INTO learned_rules (section_name, role_category, rule_instruction, triggered_by_comment, is_active) VALUES ('cover_letter', 'ALL', '${safeRule}', '${safeRule}', TRUE);`);
    }
    sqlQueries.push(`DELETE FROM job_hunter_bot_state WHERE chat_id = '${ADMIN_CHAT_ID}';`);
    const row = findRowBySNo(targetId);
    await tgPost('sendMessage', {
      chat_id: ADMIN_CHAT_ID,
      parse_mode: 'Markdown',
      disable_web_page_preview: true,
      text:
        `🛠️ *Cover Letter Rework Queued for Row #${targetId} (${row?.['Company'] || 'Target'})*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `📝 *Your Feedback:* "${text}"\n` +
        `🎯 *Scope:* *${scope === 'ONE_OFF' ? '📌 This Cover Letter Only' : '🧠 Saved to Permanent Lessons Learnt'}*\n` +
        `🔗 [View JD](${getClickableJdUrl(row)})\n\n` +
        `_Workflow 3 on Hostinger n8n will automatically rewrite the paragraph and send the updated 1-page PDF!_`,
      reply_markup: { inline_keyboard: mainMenuKeyboard }
    });
  } else if (pAct === 'SET_PORTAL_CREDS') {
    const parts = text.split('|').map(s => s.trim());
    const userVal = (parts[0] || 'user@example.com').replace(/'/g, "''");
    const passVal = (parts[1] || '').replace(/'/g, "''");
    const safeSite = String(targetId).replace(/'/g, "''");
    sqlQueries.push(`
      INSERT INTO portal_credentials_vault (site_name, login_method, auth_email, communication_email, username, encrypted_password, auth_status, updated_at)
      VALUES ('${safeSite}', 'Username & Password', '${userVal}', 'user@example.com', '${userVal}', '${passVal}', 'Authenticated', NOW())
      ON CONFLICT (site_name) DO UPDATE SET
        login_method = 'Username & Password',
        auth_email = '${userVal}',
        communication_email = 'user@example.com',
        username = '${userVal}',
        encrypted_password = '${passVal}',
        auth_status = 'Authenticated',
        updated_at = NOW();
    `);
    sqlQueries.push(`DELETE FROM job_hunter_bot_state WHERE chat_id = '${ADMIN_CHAT_ID}';`);
    trackerUpdates.push({
      'Site': targetId,
      'Authentication Status': 'Authenticated'
    });
    await tgPost('sendMessage', {
      chat_id: ADMIN_CHAT_ID,
      parse_mode: 'Markdown',
      text:
        `✅ *Credentials Saved for ${targetId}*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🔑 *Login Username:* \`${userVal}\`\n` +
        `📧 *Communication Email (Locked):* \`user@example.com\`\n` +
        `🟢 *Status:* \`Authenticated\``,
      reply_markup: { inline_keyboard: mainMenuKeyboard }
    });
  }
}

// 2. Handle Commands & Callback Queries
else if (action === '/start' || action === '/help' || action === '/menu' || action === 'cmd:menu') {
  const activeRows = jobRows.filter(r => r['Company'] || r['Position - Title']);
  const appliedCount = activeRows.filter(r => String(r['Status'] || '').toLowerCase() === 'applied').length;
  const reviewCount = activeRows.filter(r => r['Resume Status'] === 'Ready for Review' || r['Cover Letter Status'] === 'Ready for Review').length;
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    text:
      `🤖 *AI Job Hunter — Hostinger n8n Control Center*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `🌐 *Server:* \`http://localhost:11434\` _(Live 24/7)_\n` +
      `🔑 *Auth Emails:* \`user@example.com\` & \`user@example.com\`\n` +
      `📧 *Comm Email (Strict):* \`user@example.com\`\n` +
      `🧠 *Active Learned Rules:* *${learnedRulesCount}*\n` +
      `📊 *Tracker:* *${activeRows.length}* tracked roles (*${appliedCount}* Applied, *${reviewCount}* Ready for Review)\n\n` +
      `*Available Commands:*\n` +
      `• /pipeline — Live Job Application Sheet status\n` +
      `• /drafts — Approve or Rework Resumes & Cover Letters (with JD links)\n` +
      `• /eod — Consolidated In-Portal vs External Apply Summary\n` +
      `• /enrich — Fill blank cells in half-filled manual rows\n` +
      `• /edit\\_creds — Switch 008/08 SSO or reset portal credentials\n` +
      `• /mail\\_drafts — Review 2–3 day follow-up email drafts\n` +
      `• /sync\\_profile — Sync Master Resume & Coursera Certs across portals`,
    reply_markup: { inline_keyboard: mainMenuKeyboard }
  });
}

else if (action.startsWith('/pipeline') || action === 'cmd:pipeline') {
  const activeRows = jobRows.filter(r => r['Company'] || r['Position - Title']);
  const applied = activeRows.filter(r => String(r['Status'] || '').toLowerCase() === 'applied');
  const readyRes = activeRows.filter(r => r['Resume Status'] === 'Ready for Review');
  const readyCl = activeRows.filter(r => r['Cover Letter Status'] === 'Ready for Review');
  const withRef = activeRows.filter(r => String(r['Reference'] || '').trim() !== '');
  const recent5 = activeRows.slice(-6).map(r => {
    const sNo = r['S. No.'];
    const comp = r['Company'] || 'Unknown';
    const role = r['Position - Title'] || 'Role';
    const st = r['Status'] || r['Resume Status'] || 'Queued';
    const ref = r['Reference'] ? ` _(Ref: ${r['Reference']})_` : '';
    return `• *#${sNo} ${comp}* — ${role} [\`${st}\`]${ref}`;
  }).join('\n');

  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    text:
      `📊 *Live Job Application Pipeline*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `• *Total Tracked Roles:* *${activeRows.length}*\n` +
      `• *Applied:* *${applied.length}*\n` +
      `• *With Referral (Col J):* *${withRef.length}*\n` +
      `• *Resumes Ready for Review:* *${readyRes.length}*\n` +
      `• *Cover Letters Ready for Review:* *${readyCl.length}*\n\n` +
      `*Latest Entries in Sheet:*\n${recent5}\n\n` +
      `🔗 [Open Job Application Sheet](${SHEET_URL})`,
    reply_markup: { inline_keyboard: mainMenuKeyboard }
  });
}

else if (action.startsWith('/drafts') || action === 'cmd:drafts') {
  const reviewRows = jobRows.filter(r =>
    ['Ready for Review', 'Create one', 'Needs Rework'].includes(String(r['Resume Status'] || '').trim()) ||
    ['Ready for Review', 'Create one', 'Needs Rework'].includes(String(r['Cover Letter Status'] || '').trim())
  );

  if (reviewRows.length === 0) {
    await tgPost('sendMessage', {
      chat_id: ADMIN_CHAT_ID,
      parse_mode: 'Markdown',
      disable_web_page_preview: true,
      text: `✅ *All Resumes & Cover Letters are Reviewed!*\nNo pending drafts waiting for approval right now.\n\n🔗 [Open Job Application Sheet](${SHEET_URL})`,
      reply_markup: { inline_keyboard: mainMenuKeyboard }
    });
  } else {
    for (const r of reviewRows.slice(0, 5)) {
      const sNo = r['S. No.'];
      const comp = r['Company'] || 'Target Company';
      const title = r['Position - Title'] || 'Role';
      const resSt = r['Resume Status'] || 'N/A';
      const clSt = r['Cover Letter Status'] || 'Not Triggered (Staged)';
      const resUrl = r['Resume'] || SHEET_URL;
      const clUrl = r['Cover Letter'] || '';
      const jdUrl = getClickableJdUrl(r);
      const ref = r['Reference'] || 'Direct / Portal';

      const kb = [
        [
          { text: `✅ Approve Resume #${sNo}`, callback_data: `apr_res:${sNo}` },
          { text: `✅ Approve + Create CL #${sNo}`, callback_data: `apr_res_cl:${sNo}` }
        ],
        [
          { text: `📌 Rework Res (This Job)`, callback_data: `rwk_res_1:${sNo}` },
          { text: `🧠 Rework Res (Learn Rule)`, callback_data: `rwk_res_l:${sNo}` }
        ]
      ];
      if (clUrl || clSt === 'Ready for Review') {
        kb.push([
          { text: `✅ Approve CL #${sNo}`, callback_data: `apr_cl:${sNo}` },
          { text: `📌 Rework CL (This Job)`, callback_data: `rwk_cl_1:${sNo}` },
          { text: `🧠 Rework CL (Learn)`, callback_data: `rwk_cl_l:${sNo}` }
        ]);
      }

      await tgPost('sendMessage', {
        chat_id: ADMIN_CHAT_ID,
        parse_mode: 'Markdown',
        disable_web_page_preview: true,
        text:
          `📝 *Draft Review — Row #${sNo}: ${comp}*\n` +
          `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
          `💼 *Role:* ${title}\n` +
          `🤝 *Reference (Col J):* ${ref}\n` +
          `📄 *Resume Status:* \`${resSt}\`\n` +
          `✉️ *Cover Letter Status:* \`${clSt}\`\n\n` +
          `🔗 [Click to View Job Description (JD)](${jdUrl})\n` +
          `📥 [Open Tailored Resume PDF](${resUrl})` +
          (clUrl ? `\n📥 [Open Cover Letter PDF](${clUrl})` : ''),
        reply_markup: { inline_keyboard: kb }
      });
    }
  }
}

else if (action.startsWith('/eod') || action === 'cmd:eod') {
  const inPortal = eodLogs.filter(e => e.apply_channel === 'IN_PORTAL');
  const external = eodLogs.filter(e => e.apply_channel !== 'IN_PORTAL');
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    text:
      `🌙 *End-of-Day (EOD) Application Summary*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `⚡ *Jobs Applied Inside Portals (Silent Easy/1-Click Apply):* *${inPortal.length}*\n` +
      (inPortal.map(j => `  • *#${j.s_no} ${j.company_name}* — ${j.position_title} _(${j.portal_name})_`).join('\n') || '  • None') +
      `\n\n🌐 *Jobs Applied Outside Portals (External Company Websites):* *${external.length}*\n` +
      (external.map(j => `  • *#${j.s_no} ${j.company_name}* — ${j.position_title} _(${j.portal_name})_`).join('\n') || '  • None') +
      `\n\n📧 *Communication Email Used:* \`user@example.com\`\n` +
      `📊 [Open Job Application Sheet](${SHEET_URL})`,
    reply_markup: { inline_keyboard: mainMenuKeyboard }
  });
}

else if (action.startsWith('/enrich') || action === 'cmd:enrich') {
  // Trigger Workflow 4 or enrich directly
  let enriched = 0;
  for (const r of jobRows) {
    const sNo = String(r['S. No.'] || '').trim();
    if (!sNo) continue;
    const title = String(r['Position - Title'] || '').trim();
    const jd = String(r['Position - Description'] || '').trim();
    const comp = String(r['Company'] || '').trim();
    const status = String(r['Status'] || '').trim();
    if (!title && !jd && !comp && !status) continue;

    const patch = { 'S. No.': sNo };
    let changed = false;
    if (!String(r['Resume_id'] || '').trim()) { patch['Resume_id'] = `RES-${sNo}`; changed = true; }
    if (!String(r['Industry'] || '').trim()) { patch['Industry'] = 'Technology & Data Analytics'; changed = true; }
    if (!String(r['Location'] || '').trim()) { patch['Location'] = 'India (Hybrid / Remote)'; changed = true; }
    if (status.toLowerCase() === 'applied' && !String(r['Follow up Date'] || '').trim()) {
      const d = new Date(); d.setDate(d.getDate() + 3);
      patch['Follow up Date'] = `${d.getMonth() + 1}/${d.getDate()}/${d.getFullYear()}`;
      changed = true;
    }
    if (changed) {
      sheetUpdates.push(patch);
      enriched++;
    }
  }
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    text:
      `✨ *Non-Destructive Sheet Enrichment Complete*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `• *Rows Enriched (Blank Cells Only):* *${enriched}*\n` +
      `• *Manual Values Overwritten:* *0* _(Strict Non-Destructive Guard Active)_\n` +
      `• *Referral Column Checked:* Column \`J\` (\`Reference\`)\n\n` +
      `🔗 [Open Job Application Sheet](${SHEET_URL})`,
    reply_markup: { inline_keyboard: mainMenuKeyboard }
  });
}

else if (action.startsWith('/edit_creds') || action === 'cmd:edit_creds') {
  const lines = vaultRows.map(v => {
    const icon = v.auth_status === 'Authenticated' ? '🟢' : '🟡';
    return `${icon} *${v.site_name}* — \`${v.login_method}\` (\`${v.auth_email}\`)`;
  }).join('\n');

  const kb = [];
  for (let i = 0; i < vaultRows.length; i += 2) {
    const rowBtns = [];
    rowBtns.push({ text: `⚙️ ${vaultRows[i].site_name}`, callback_data: `cred_view:${vaultRows[i].site_name}` });
    if (vaultRows[i + 1]) {
      rowBtns.push({ text: `⚙️ ${vaultRows[i + 1].site_name}`, callback_data: `cred_view:${vaultRows[i + 1].site_name}` });
    }
    kb.push(rowBtns);
  }
  kb.push([{ text: '🔙 Back to Main Menu', callback_data: 'cmd:menu' }]);

  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text:
      `🔐 *Dual-Email Portal Credential Vault*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `📧 *Outbound Communication Email (Locked):*\n` +
      `\`user@example.com\`\n\n` +
      `🔑 *Supported Login Accounts:*\n` +
      `• \`user@example.com\`\n` +
      `• \`user@example.com\`\n\n` +
      `*Configured Portals:*\n${lines || 'No portals found'}\n\n` +
      `_Tap any portal below to switch between 008 & 08, set a password, or remove/reset earlier credentials:_`,
    reply_markup: { inline_keyboard: kb }
  });
}

else if (action.startsWith('cred_view:')) {
  const site = action.slice('cred_view:'.length);
  const v = vaultRows.find(x => x.site_name === site) || { site_name: site, login_method: 'Not Set', auth_email: 'user@example.com', auth_status: 'Authentication pending' };
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text:
      `⚙️ *Manage Credentials — ${site}*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `• *Status:* \`${v.auth_status}\`\n` +
      `• *Login Method:* \`${v.login_method}\`\n` +
      `• *Auth Email:* \`${v.auth_email}\`\n` +
      `• *Communication Email (Locked):* \`user@example.com\`\n\n` +
      `_Choose an action for ${site}:_`,
    reply_markup: {
      inline_keyboard: [
        [
          { text: '🟢 Use Google SSO (008@gmail)', callback_data: `cred_008:${site}` },
          { text: '🔵 Use Google SSO (08@gmail)', callback_data: `cred_08:${site}` }
        ],
        [
          { text: '🔑 Set Username & Password', callback_data: `cred_pw:${site}` },
          { text: '🗑️ Remove / Reset Credentials', callback_data: `cred_del:${site}` }
        ],
        [
          { text: '🔙 Back to Vault', callback_data: 'cmd:edit_creds' }
        ]
      ]
    }
  });
}

else if (action.startsWith('cred_008:') || action.startsWith('cred_08:')) {
  const is008 = action.startsWith('cred_008:');
  const site = action.split(':')[1];
  const email = is008 ? 'user@example.com' : 'user@example.com';
  const method = is008 ? 'Google SSO / OTP (008)' : 'Google SSO / OTP (08)';
  const safeSite = site.replace(/'/g, "''");
  sqlQueries.push(`
    INSERT INTO portal_credentials_vault (site_name, login_method, auth_email, communication_email, auth_status, updated_at)
    VALUES ('${safeSite}', '${method}', '${email}', 'user@example.com', 'Authenticated', NOW())
    ON CONFLICT (site_name) DO UPDATE SET
      login_method = '${method}',
      auth_email = '${email}',
      communication_email = 'user@example.com',
      auth_status = 'Authenticated',
      updated_at = NOW();
  `);
  trackerUpdates.push({
    'Site': site,
    'Authentication Status': 'Authenticated'
  });
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text:
      `✅ *Updated ${site} Authentication*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `• *New Login Account:* \`${email}\` (${method})\n` +
      `• *Communication Email (Locked):* \`user@example.com\`\n` +
      `• *Status:* \`Authenticated\``,
    reply_markup: { inline_keyboard: [[{ text: '🔐 Back to Credential Vault', callback_data: 'cmd:edit_creds' }]] }
  });
}

else if (action.startsWith('cred_del:')) {
  const site = action.slice('cred_del:'.length);
  const safeSite = site.replace(/'/g, "''");
  sqlQueries.push(`
    UPDATE portal_credentials_vault
    SET login_method = 'Reset / Removed',
        username = NULL,
        encrypted_password = NULL,
        auth_status = 'Authentication pending',
        updated_at = NOW()
    WHERE site_name = '${safeSite}';
  `);
  trackerUpdates.push({
    'Site': site,
    'Authentication Status': 'Authentication pending'
  });
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text:
      `🗑️ *Removed Saved Credentials for ${site}*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Earlier credentials/SSO session for *${site}* have been wiped and status reset to \`Authentication pending\`.\n\n` +
      `_Select a new login method below whenever you are ready:_`,
    reply_markup: {
      inline_keyboard: [
        [
          { text: '🟢 Set SSO (008@gmail)', callback_data: `cred_008:${site}` },
          { text: '🔵 Set SSO (08@gmail)', callback_data: `cred_08:${site}` }
        ],
        [
          { text: '🔑 Set Username & Password', callback_data: `cred_pw:${site}` }
        ]
      ]
    }
  });
}

else if (action.startsWith('cred_pw:')) {
  const site = action.slice('cred_pw:'.length);
  const safeSite = site.replace(/'/g, "''");
  sqlQueries.push(`
    INSERT INTO job_hunter_bot_state (chat_id, pending_action, target_id, scope, updated_at)
    VALUES ('${ADMIN_CHAT_ID}', 'SET_PORTAL_CREDS', '${safeSite}', 'VAULT', NOW())
    ON CONFLICT (chat_id) DO UPDATE SET
      pending_action = 'SET_PORTAL_CREDS',
      target_id = '${safeSite}',
      scope = 'VAULT',
      updated_at = NOW();
  `);
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text:
      `🔑 *Set Username & Password for ${site}*\n` +
      `Please reply to this message in the format:\n` +
      `\`username_or_email | password\`\n\n` +
      `_(Note: Outbound communication email will still remain strictly \`user@example.com\`)_`
  });
}

else if (action.startsWith('apr_res:') || action.startsWith('apr_res_cl:')) {
  const withCl = action.startsWith('apr_res_cl:');
  const sNo = action.split(':')[1];
  const row = findRowBySNo(sNo);
  const jdText = String(row?.['Position - Description'] || '');
  const autoNeedsCl = withCl || /cover\s*letter/i.test(jdText) || String(row?.['Notes for CL'] || '').includes('MODAL_CL_REQUIRED');

  const patch = {
    'S. No.': String(sNo),
    'Resume Status': 'LGTM'
  };
  if (autoNeedsCl) {
    patch['Cover Letter Status'] = 'Create one';
  }
  sheetUpdates.push(patch);

  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    text:
      `✅ *Stage 1 Approved: Resume Marked LGTM (Row #${sNo} — ${row?.['Company'] || 'Target'})*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `• *Resume Status:* \`LGTM\` _(Workflow 2 will promote to Few-Shot Library)_\n` +
      (autoNeedsCl
        ? `• *Stage 2 Triggered:* \`Cover Letter Status = Create one\` _(Workflow 3 will now generate the 1-page grounded Cover Letter!)_`
        : `• *Cover Letter:* Not required for this role _(Tap below if you still want one generated)_`),
    reply_markup: {
      inline_keyboard: autoNeedsCl
        ? mainMenuKeyboard
        : [[{ text: `📝 Generate Cover Letter for #${sNo}`, callback_data: `apr_res_cl:${sNo}` }], ...mainMenuKeyboard]
    }
  });
}

else if (action.startsWith('apr_cl:')) {
  const sNo = action.split(':')[1];
  const row = findRowBySNo(sNo);
  sheetUpdates.push({
    'S. No.': String(sNo),
    'Cover Letter Status': 'LGTM'
  });
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text:
      `✅ *Stage 2 Approved: Cover Letter Marked LGTM (Row #${sNo} — ${row?.['Company'] || 'Target'})*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Both your tailored Resume and 1-page Cover Letter are approved and promoted to the Few-Shot Library!`,
    reply_markup: { inline_keyboard: mainMenuKeyboard }
  });
}

else if (action.startsWith('rwk_res_1:') || action.startsWith('rwk_res_l:') || action.startsWith('rwk_cl_1:') || action.startsWith('rwk_cl_l:')) {
  const parts = action.split(':');
  const prefix = parts[0];
  const sNo = parts[1];
  const isRes = prefix.startsWith('rwk_res');
  const scope = prefix.endsWith('_1') ? 'ONE_OFF' : 'LEARN';
  const pAct = isRes ? 'REWORK_RESUME' : 'REWORK_CL';
  const row = findRowBySNo(sNo);

  sqlQueries.push(`
    INSERT INTO job_hunter_bot_state (chat_id, pending_action, target_id, scope, updated_at)
    VALUES ('${ADMIN_CHAT_ID}', '${pAct}', '${sNo}', '${scope}', NOW())
    ON CONFLICT (chat_id) DO UPDATE SET
      pending_action = '${pAct}',
      target_id = '${sNo}',
      scope = '${scope}',
      updated_at = NOW();
  `);

  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    text:
      `✏️ *Send Rework Instructions for ${isRes ? 'Resume' : 'Cover Letter'} #${sNo} (${row?.['Company'] || 'Target'})*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `🎯 *Selected Scope:* *${scope === 'ONE_OFF' ? '📌 This Job Only (Will NOT be saved to Lessons Learnt)' : '🧠 Save to Permanent Lessons Learnt'}*\n` +
      `🔗 [Click to View JD](${getClickableJdUrl(row)})\n\n` +
      `_Reply to this message with the exact changes you want:_`
  });
}

else if (action.startsWith('/mail_drafts') || action === 'cmd:mail_drafts') {
  const pendingDrafts = followupDrafts.filter(d => d.status === 'Pending Approval');
  if (pendingDrafts.length === 0) {
    // Check if any Applied rows with Reference need a draft shown
    const refApplied = jobRows.filter(r => String(r['Status'] || '').toLowerCase() === 'applied' && String(r['Reference'] || '').trim() !== '');
    const sampleList = refApplied.map(r => `• *#${r['S. No.']} ${r['Company']}* — Ref: *${r['Reference']}* (Follow-up Date: \`${r['Follow up Date'] || 'Set'}\`)`).join('\n');
    await tgPost('sendMessage', {
      chat_id: ADMIN_CHAT_ID,
      parse_mode: 'Markdown',
      text:
        `📬 *Follow-Up Email Drafts Queue*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `📧 *Sender (Strict):* \`user@example.com\`\n` +
        `No overdue unapproved follow-up drafts right now.\n\n` +
        `*Upcoming Scheduled Follow-Ups (Col J Reference):*\n${sampleList || '• None'}`,
      reply_markup: { inline_keyboard: mainMenuKeyboard }
    });
  } else {
    for (const d of pendingDrafts.slice(0, 5)) {
      await tgPost('sendMessage', {
        chat_id: ADMIN_CHAT_ID,
        parse_mode: 'Markdown',
        text:
          `📬 *Follow-Up Draft (${d.draft_id}) — ${d.company_name}*\n` +
          `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
          `• *From:* \`user@example.com\`\n` +
          `• *To / Reference:* ${d.recipient_name || 'Hiring Team'}\n` +
          `• *Subject:* ${d.subject}\n\n` +
          `\`\`\`\n${d.body_text}\n\`\`\``,
        reply_markup: {
          inline_keyboard: [
            [
              { text: '✅ Approve & Mark Sent', callback_data: `mail_apr:${d.draft_id}:${d.s_no}` },
              { text: '🗑️ Discard', callback_data: `mail_del:${d.draft_id}` }
            ]
          ]
        }
      });
    }
  }
}

else if (action.startsWith('/sync_profile') || action === 'cmd:sync_profile') {
  await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    parse_mode: 'Markdown',
    text: `🔄 *Triggering Workflow 6 (Workflow B — Master Resume, 14 Skills & 10 Certifications Portal Sync)...*`
  });
}

let targetWorkflowId = '';
if (action.startsWith('/sync_profile') || action === 'cmd:sync_profile') {
  targetWorkflowId = 'QL9218oxuBxpYefQ';
} else if (action.startsWith('/enrich') || action === 'cmd:enrich') {
  targetWorkflowId = 'kYpYvF2pM66RYXCC';

} else if (action.startsWith('apr_res:')) {
  targetWorkflowId = 'lXNGL9OcyVVtCBuz';
} else if (action.startsWith('apr_res_cl:') || action.startsWith('apr_cl:')) {
  targetWorkflowId = 'T4k9rXZ2CKK72xZS';
} else if (!cbData && text && !text.startsWith('/') && botState.pending_action === 'REWORK_RESUME') {
  targetWorkflowId = 'lXNGL9OcyVVtCBuz';
} else if (!cbData && text && !text.startsWith('/') && botState.pending_action === 'REWORK_CL') {
  targetWorkflowId = 'T4k9rXZ2CKK72xZS';
}

return [{
  json: {
    ok: true,
    action,
    targetWorkflowId,
    shouldExecuteSubworkflow: Boolean(targetWorkflowId),
    sheetUpdates,
    trackerUpdates,
    combinedSql: sqlQueries.length > 0 ? sqlQueries.join('\n') : 'SELECT 1;'
  }
}];
